import{_ as i,a0 as r,w as a,s as m,I as n,x as o,a1 as e,A as l,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"NMAP 常用掃描簡介（二） | LCTT x X-CMD","titleTemplate":false,"description":"NMAP 常用掃描簡介（二） | LCTT (201704) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"NMAP 常用掃描簡介（二） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"NMAP 常用掃描簡介（二） | LCTT (201704) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201704/20170125 NMAP Common Scans – Part Two","title":"NMAP 常用掃描簡介（二）","tag":"201704","desc":""},"relativePath":"201704/20170125 NMAP Common Scans – Part Two.md","filePath":"[post].md"}'),P={name:"201704/20170125 NMAP Common Scans – Part Two.md"};function C(T,t,d,u,N,S){const p=r("Link");return a(),m("div",null,[t[19]||(t[19]=n("h1",{id:"nmap-常用掃描簡介-二",tabindex:"-1"},[o("NMAP 常用掃描簡介（二） "),n("a",{class:"header-anchor",href:"#nmap-常用掃描簡介-二","aria-label":"Permalink to “NMAP 常用掃描簡介（二）”"},"​")],-1)),n("p",null,[t[1]||(t[1]=o("在我們之前的 ",-1)),e(p,{href:"https://www.linuxforum.com/threads/nmap-installation.3431/"},{default:l(()=>[...t[0]||(t[0]=[o("NMAP 安裝",-1)])]),_:1}),t[2]||(t[2]=o("一文中，列出了 10 種不同的 ZeNMAP 掃描模式，大多數的模式使用了不同的參數。各種不同參數代表執行不同的掃描模式。這篇文章將介紹最後剩下的兩種常用掃描類型。",-1))]),t[20]||(t[20]=s('<h3 id="四種通用掃描類型" tabindex="-1">四種通用掃描類型 <a class="header-anchor" href="#四種通用掃描類型" aria-label="Permalink to “四種通用掃描類型”">​</a></h3><p>下面列出了最常用的四種掃描類型：</p><ol><li>PING 掃描（<code>-sP</code>）</li><li>TCP SYN 掃描（<code>-sS</code>）</li><li>TCP Connect() 掃描（<code>-sT</code>）</li><li>UDP 掃描（<code>-sU</code>）</li></ol><p>當我們利用 NMAP 來執行掃描的時候，這四種掃描類型是我們需要熟練掌握的。更重要的是需要知道這些命令做了什麼，並且需要知道這些命令是怎麼做的。在這篇文章中將介紹兩種 TCP 掃描 — TCP SYN 掃描和 TCP Connect() 掃描。</p>',4)),n("p",null,[t[4]||(t[4]=o("(",-1)),e(p,{href:"https://linux.cn/article-8346-1.html%EF%BC%8F"},{default:l(()=>[...t[3]||(t[3]=[o("閲讀 NMAP 常用掃描簡介（一）",-1)])]),_:1}),t[5]||(t[5]=o(")",-1))]),t[21]||(t[21]=s('<h3 id="tcp-syn-掃描-ss" tabindex="-1">TCP SYN 掃描 （-sS） <a class="header-anchor" href="#tcp-syn-掃描-ss" aria-label="Permalink to “TCP SYN 掃描 （-sS）”">​</a></h3><p>TCP SYN 掃描是默認的 NMAP 掃描方式。為了運行 TCP SYN 掃描，你需要有 Root 權限。</p><p>TCP SYN 掃描的目的是找到被掃描系統上的已開啓端口。使用 NMAP 掃描可以掃描在防火牆另一側的系統。當掃描通過防火牆時，掃描時間會延長，因為數據包會變慢。</p><p>TCP SYN 掃描的工作方式是啓動一個“三次握手”。正如在另一篇文章中所述，“三次握手”發生在兩個系統之間。首先，源系統發送一個包到目標系統，這是一個同步（SYN）請求。然後，目標系統將通過同步/應答（SYN/ACK）響應。接下來，源系統將通過應答（ACK）來響應，從而建立起一個通信連接，然後，可以在兩個系統之間傳輸數據。</p><p>TCP SYN 掃描通過執行下面的步驟來進行工作：</p><ol><li>源系統向目標系統發送一個同步請求，該請求中包含一個端口號。</li><li>如果添加在上一步中的所請求的端口號是開啓的，那麼目標系統將通過同步/應答（SYN/ACK）來響應源系統。</li><li>源系統通過重置（RST）來響應目標系統，從而斷開連接。</li><li>目標系統可以通過重置/應答（RST/ACK）來響應源系統。</li></ol><p>這種連接已經開始建立，所以這被認為是半開放連接。因為連接狀態是由 NMAP 來管理的，所以你需要有 Root 權限。</p><p>如果被掃描的端口是關閉的，那麼將執行下面的步驟：</p><ol><li>源系統發送一個同步（SYN）請求到目標系統，該請求中包含一個端口號。</li><li>目標系統通過重置（RST）響應源系統，因為該端口是關閉的。</li></ol><p>如果目標系統處於防火牆之後，那麼 ICMP 傳輸或響應會被防火牆禁止，此時，會執行下面的步驟：</p><ol><li>源系統發送一個同步（SYN）請求到目標系統，該請求中包含一個端口號。</li><li>沒有任何響應，因為請求被防火牆過濾了。</li></ol><p>在這種情況下，端口可能是被過濾、或者可能打開、或者可能沒打開。防火牆可以設置禁止指定端口所有包的傳出。防火牆可以禁止所有傳入某個指定端口的包，因此目標系統不會接收到請求。</p><p><strong>注：</strong>無響應可能發生在一個啓用了防火牆的系統上。即使在本地網絡，你也可能會發現被過濾的端口。</p><p>我將向 圖片１那樣執行對單一系統（10.0.0.2）的 TCP SYN 掃描。使用命令 <code>sudo nmap -sS &lt;IP 地址&gt;</code> 來執行掃描。<code>&lt;IP 地址&gt;</code>可以改為一個單一 IP 地址，像圖片１那樣，也可以使用一組 IP 地址。</p><p><img src="https://www.linuxforum.com/attachments/figure-01-jpg.119/" alt="Figure 01.jpg"></p><p><em>圖片１</em></p><p>你可以看到它表明 997 個被過濾端口沒有顯示在下面。NMAP 找到兩個開啓的端口：139 和 445 。</p><p><strong>注：</strong>請記住，NMAP 只會掃描絕大多數熟知的 1000 多個端口。以後，我們會介紹可以掃描所有端口或者指定端口的其它掃描。</p><p>該掃描會被 WireShark 俘獲，正如圖片２所展示的那樣。在這兒，你可以看到對目標系統的初始地址解析協議（ARP）請求。在 ARP 請求下面的是一長列到達目標系統端口的 TCP 請求。第 4 行是到達 <code>http-alt</code> 端口（8080）。源系統的端口號為 47128 。正如圖片３ 展示的，許多 SYN 請求只有在做出響應以後才會發送。</p><p><img src="https://www.linuxforum.com/attachments/figure-2-jpg.120/" alt="Figure 2.jpg"></p><p><em>圖片２</em></p><p><img src="https://www.linuxforum.com/attachments/figure-3-jpg.121/" alt="Figure 3.jpg"></p><p><em>圖片３</em></p><p>在圖片３的第 50 行和第 51 行，你可以看到，重置（RST）包被髮送給了目標系統。第 53 行和第 55 行顯示目標系統的 RST/ACK（重置/應答）。第 50 行是針對 ‘microsoft-ds’ 端口（445），第 51 行是針對 ‘netbios-ssn’ 端口（135），我們可以看到，這兩個端口都是打開的。（LCTT 譯註：在 50 行和 51 行之前，目標系統發回了 SYN/ACK 響應，表示端口打開。）除了這些端口，沒有其他 ACK（應答）是來自目標系統的。每一個請求均可發送超過 1000 次。</p><p>正如圖片４所展示的，目標系統是 Windows 系統，我關閉了系統防火牆，然後再次執行掃描。現在，我們看到了 997 個已關閉端口不是 997 個被過濾端口。目標系統上的 135 端口之前被防火牆禁止了，現在也是開啓的。</p><p><img src="https://www.linuxforum.com/attachments/figure-04-jpg.122/" alt="Figure 04.jpg"></p><p><em>圖片４</em></p><h3 id="tcp-connect-掃描-st" tabindex="-1">TCP Connect() 掃描 （-sT） <a class="header-anchor" href="#tcp-connect-掃描-st" aria-label="Permalink to “TCP Connect() 掃描 （-sT）”">​</a></h3><p>儘管 TCP SYN 掃描需要 Root 權限，但 TCP Connect() 掃描並不需要。在這種掃描中會執行一個完整的“三次握手”。因為不需要 Root 權限，所以在無法獲取 Root 權限的網絡上，這種掃描非常有用。</p><p>TCP Connect() 掃描的工作方式也是執行“三次握手”。正如上面描述過的，“三次握手”發生在兩個系統之間。源系統發送一個同步（SYN）請求到目標系統。然後，目標系統將通過同步／應答（SYN/ACK）來響應。最後，源系統通過應答（ACK）來響應，從而建立起連接，然後便可在兩個系統之間傳輸數據。</p><p>TCP Connect 掃描通過執行下面的步驟來工作：</p><ol><li>源系統發送一個同步（SYN）請求到目標系統，該請求中包含一個端口號。</li><li>如果上一步所請求的端口是開啓的，那麼目標系統將通過同步/應答（SYN/ACK）來響應源系統。</li><li>源系統通過應答（ACK）來響應目標系統從而完成會話創建。</li><li>然後，源系統向目標系統發送一個重置（RST）包來關閉會話。</li><li>目標系統可以通過同步/應答（SYN/ACK）來響應源系統。</li></ol><p>若步驟 2 執行了，那麼源系統就知道在步驟 1 中的指定端口是開啓的。</p><p>如果端口是關閉的，那麼會發生和 TCP SYN 掃描相同的事。在步驟 2 中，目標系統將會通過一個重置（RST）包來響應源系統。</p><p>可以使用命令 <code>nmap -sT &lt;IP 地址&gt;</code> 來執行掃描。<code>&lt;IP 地址&gt;</code>可以改為一個單一 IP 地址，像圖片５那樣，或者使用一組 IP 地址。</p><p>TCP Connect() 掃描的結果可以在圖片５中看到。在這兒，你可以看到，有兩個已開啓端口：139 和 445，這和 TCP SYN 掃描的發現一樣。端口 80 是關閉的。剩下沒有顯示的端口是被過濾了的。</p><p><img src="https://www.linuxforum.com/attachments/figure-05-jpg.123/" alt="Figure 05.jpg"></p><p><em>圖片５</em></p><p>讓我們關閉防火牆以後再重新掃描一次，掃描結果展示在圖片６中。</p><p><img src="https://www.linuxforum.com/attachments/figure-06-jpg.124/" alt="Figure 06.jpg"></p><p><em>圖片６</em></p><p>關閉防火牆以後，我們可以看到，更多的端口被發現了。就和 TCP SYN 掃描一樣，關閉防火牆以後，發現 139 端口和 445 端口是開啓的。我們還發現，端口 2869 也是開啓的。也發現有 996 個端口是關閉的。現在，端口 80 是 996 個已關閉端口的一部分 — 不再被防火牆過濾。</p><p>在一些情況下， TCP Connect() 掃描可以在一個更短的時間內完成。和 TCP SYN 掃描相比，TCP Connect() 掃描也可以找到更多的已開啓端口</p><hr>',44)),n("p",null,[t[7]||(t[7]=o("via: ",-1)),e(p,{href:"https://www.linuxforum.com/threads/nmap-common-scans-part-two.3879/"},{default:l(()=>[...t[6]||(t[6]=[o("https://www.linuxforum.com/threads/nmap-common-scans-part-two.3879/",-1)])]),_:1})]),n("p",null,[t[11]||(t[11]=o("作者：",-1)),e(p,{href:"https://www.linuxforum.com/members/jarret.268/"},{default:l(()=>[...t[8]||(t[8]=[o("Jarret",-1)])]),_:1}),t[12]||(t[12]=o(" 譯者：",-1)),e(p,{href:"https://github.com/ucasFL"},{default:l(()=>[...t[9]||(t[9]=[o("ucasFL",-1)])]),_:1}),t[13]||(t[13]=o(" 校對：",-1)),e(p,{href:"https://github.com/wxy"},{default:l(()=>[...t[10]||(t[10]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[16]||(t[16]=o("本文由 ",-1)),e(p,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[14]||(t[14]=[o("LCTT",-1)])]),_:1}),t[17]||(t[17]=o(" 原創編譯，",-1)),e(p,{href:"https://linux.cn/"},{default:l(()=>[...t[15]||(t[15]=[o("Linux中國",-1)])]),_:1}),t[18]||(t[18]=o(" 榮譽推出",-1))])])}const A=i(P,[["render",C]]);export{w as __pageData,A as default};
